INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2438320, 335257, 11843, '<td valign="top">Really good portrayal of emotion on this very controversial subject. I like the muted color too. The slanting wall in the background seems a bit distracting to the composition. Nit picky really...Great work.</td>', 'Really good portrayal of emotion on this very controversial subject. I like the muted color too. The slanting wall in the background seems a bit distracting to the composition. Nit picky really...Great work.', '2006-05-19 23:18:21.000000', NULL, 1),
(2438325, 336094, 11843, '<td valign="top">Very moody effect going on here. The sepia makes it look like an old photo, like the skates have been hanging there for some time. Time to dust off the old friends and get out there on the ice. Well done.</td>', 'Very moody effect going on here. The sepia makes it look like an old photo, like the skates have been hanging there for some time. Time to dust off the old friends and get out there on the ice. Well done.', '2006-05-19 23:20:12.000000', NULL, 1),
