(2438698, 333255, 55642, '<td valign="top">My favorite detail is the sunlight filtered through the blinds onto your shoulder. Very nice!</td>', 'My favorite detail is the sunlight filtered through the blinds onto your shoulder. Very nice!', '2006-05-20 00:36:55.000000', NULL, 1),
(2438699, 336388, 55642, '<td valign="top">Hehe, cute!</td>', 'Hehe, cute!', '2006-05-20 00:37:14.000000', NULL, 1),
