(2444783, 333481, 11843, '<td valign="top">Good light and color. A little soft and dof too shallow.</td>', 'Good light and color. A little soft and dof too shallow.', '2006-05-22 00:16:42.000000', NULL, 1),
(2444789, 336341, 52336, '<td valign="top">A bit out of focus, and unfortunately not that appealing in terms of composition, background, tone, etc.</td>', 'A bit out of focus, and unfortunately not that appealing in terms of composition, background, tone, etc.', '2006-05-22 00:17:06.000000', NULL, 1),
