(2457374, 333467, 20530, '<td valign="top">Creative, unique, expressive and interesting. Great timing and placement of the fish, too.</td>', 'Creative, unique, expressive and interesting. Great timing and placement of the fish, too.', '2006-05-25 17:50:56.000000', NULL, 1),
(2457376, 334999, 39484, '<td valign="top">Good that you took the shot in an unusual location.  points for that.  Got to get that sharpness though if you want to please the focus freaks on dpc.</td>', 'Good that you took the shot in an unusual location.  points for that.  Got to get that sharpness though if you want to please the focus freaks on dpc.', '2006-05-25 17:52:03.000000', NULL, 1),
(2457379, 335799, 39484, '<td valign="top">Nice shot.  I think it needs a bit of contrast ie push the blacks blacker.</td>', 'Nice shot.  I think it needs a bit of contrast ie push the blacks blacker.', '2006-05-25 17:52:42.000000', NULL, 1),
(2457382, 334047, 59574, '<td valign="top">Beautiful and compelling.  Love it.</td>', 'Beautiful and compelling.  Love it.', '2006-05-25 17:53:46.000000', NULL, 1),
